```
import type { Camera } from "@babylonjs/lite";
import {
  getEffectiveAspectRatio,
  getViewMatrix,
  getViewProjectionMatrix,
  projectWorldToScreen,
  resolveCameraViewport,
} from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };
export interface ShiftTracker { mark(): void; shift(point: Vec): { dx: number; dy: number } }

type Mat4 = ReturnType<typeof getViewMatrix>;
type PixelViewport = { x: number; y: number; width: number; height: number };

interface Snapshot {
  view: Mat4;
  viewProjection: Mat4;
  viewport: PixelViewport;
  backingWidth: number;
  backingHeight: number;
  cssWidth: number;
  cssHeight: number;
}

function cloneMat4(source: Mat4): Mat4 {
  const src = source as unknown as ArrayLike<number>;
  const out = new Float32Array(16);
  for (let i = 0; i < 16; i++) {
    out[i] = src[i] ?? 0;
  }
  return out as unknown as Mat4;
}

function canvasSize(canvas: HTMLCanvasElement) {
  const cssWidth = canvas.clientWidth || canvas.width;
  const cssHeight = canvas.clientHeight || canvas.height;
  const backingWidth = canvas.width || cssWidth;
  const backingHeight = canvas.height || cssHeight;
  return { cssWidth, cssHeight, backingWidth, backingHeight };
}

function makeSnapshot(camera: Camera, canvas: HTMLCanvasElement): Snapshot {
  const { cssWidth, cssHeight, backingWidth, backingHeight } = canvasSize(canvas);
  const aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const safeAspect = Number.isFinite(aspect) && aspect > 0 ? aspect : 1;
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, safeAspect);
  return {
    view: cloneMat4(view),
    viewProjection: cloneMat4(viewProjection),
    viewport,
    backingWidth,
    cssWidth,
    cssHeight,
  };
}

function projectNow(camera: Camera, canvas: HTMLCanvasElement, point: Vec) {
  const { cssWidth, cssHeight, backingWidth, backingHeight } = canvasSize(canvas);
  const aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const safeAspect = Number.isFinite(aspect) && aspect > 0 ? aspect : 1;
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, safeAspect);
  return projectWorldToScreen(point, view, viewProjection, {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
  });
}

export function trackScreenShift(camera: Camera, canvas: HTMLCanvasElement): ShiftTracker {
  let snapshot: Snapshot | null = null;

  const tracker: ShiftTracker = {
    mark() {
      snapshot = makeSnapshot(camera, canvas);
    },
    shift(point: Vec) {
      const current = projectNow(camera, canvas, point);
      const then = snapshot
        ? projectWorldToScreen(point, snapshot.view, snapshot.viewProjection, {
            viewport: snapshot.viewport,
            backingWidth: snapshot.backingWidth,
            backingHeight: snapshot.backingHeight,
            cssWidth: snapshot.cssWidth,
            cssHeight: snapshot.cssHeight,
          })
        : current;
      const dx = current.cssX - then.cssX;
      const dy = current.cssY - then.cssY;
      return { dx: Number.isFinite(dx) ? dx : 0, dy: Number.isFinite(dy) ? dy : 0 };
    },
  };

  tracker.mark();
  return tracker;
}
```

